import{_ as t,c as e,o as l,V as r}from"./chunks/framework.tJhZUYt7.js";const d=JSON.parse('{"title":"一、三大组件","description":"","frontmatter":{},"headers":[],"relativePath":"rear/netty/nio/三大组件.md","filePath":"rear/netty/nio/三大组件.md","lastUpdated":null}'),n={name:"rear/netty/nio/三大组件.md"},o=r('<h1 id="一、三大组件" tabindex="-1">一、三大组件 <a class="header-anchor" href="#一、三大组件" aria-label="Permalink to &quot;一、三大组件&quot;">​</a></h1><p>Netty 的核心组件是 <strong>Channel（通道）、Buffer（缓冲区）、Selector（选择器）</strong>，三者配合实现高效的 IO 操作</p><ul><li><strong>Channel</strong>：负责网络 / 文件 IO 的 “连接 / 传输载体”，是数据读写的通道；</li><li><strong>Buffer</strong>：负责数据的 “临时存储缓冲”，是 IO 操作中数据的容器；</li><li><strong>Selector</strong>：负责 “多路复用”，可同时监听多个 Channel 的 IO 事件</li></ul><h2 id="一、channel" tabindex="-1">一、Channel <a class="header-anchor" href="#一、channel" aria-label="Permalink to &quot;一、Channel&quot;">​</a></h2><ol><li><strong>FileChannel</strong><ul><li>作用：用于<strong>文件 IO 操作</strong>的通道，负责本地文件的读写（非网络通信场景）；</li><li>特点：是 Java NIO 的基础实现，Netty 中可用于文件传输类业务。</li></ul></li><li><strong>DatagramChannel</strong><ul><li>作用：基于<strong>UDP 协议</strong>的网络通道，负责无连接的数据包传输；</li><li>特点：适用于低延迟、无需可靠传输的场景（如实时通信、广播）。</li></ul></li><li><strong>SocketChannel</strong><ul><li>作用：基于<strong>TCP 协议</strong>的<strong>客户端通道</strong>，负责与 TCP 服务端建立连接并传输数据；</li><li>特点：是 Netty 中实现 TCP 客户端通信的核心通道类型。</li></ul></li><li><strong>ServerSocketChannel</strong><ul><li>作用：基于<strong>TCP 协议</strong>的<strong>服务端监听通道</strong>，负责绑定端口、监听客户端连接请求；</li><li>特点：Netty 服务端启动时，会通过它绑定端口并接收客户端连接，再为每个连接创建<code>SocketChannel</code>。</li></ul></li></ol><h2 id="二、buffer" tabindex="-1">二、Buffer <a class="header-anchor" href="#二、buffer" aria-label="Permalink to &quot;二、Buffer&quot;">​</a></h2><ol><li>**ByteBuffer（核心缓冲类型）**是最常用的 Buffer，用于字节数据的缓冲，其下又分 3 个子类： <ul><li><strong>MappedByteBuffer</strong>：基于 “内存映射文件” 的缓冲，直接映射磁盘文件到内存，适合大文件读写；</li><li><strong>DirectByteBuffer</strong>：“直接内存缓冲区”，内存分配在 JVM 堆外，减少堆内存拷贝，性能更高（<strong>Netty 默认优先使用</strong>）；</li><li><strong>HeapByteBuffer</strong>：“堆内存缓冲区”，内存分配在 JVM 堆中，读写效率略低于直接内存，但便于 GC 管理。</li></ul></li><li>**其他类型 Buffer（ShortBuffer/IntBuffer 等）**对应 Java 基本数据类型（short/int/long 等）的专用缓冲，用于存储对应类型的数据，避免字节转换的开销，比如<code>IntBuffer</code>专门缓冲 int 类型数据。 <ul><li>ShortBuffer</li><li>IntBuffer</li><li>LongBuffer</li><li>FloatBuffer</li><li>DoubleBuffer</li><li>CharBuffer</li></ul></li></ol>',7),i=[o];function a(s,f,u,g,c,h){return l(),e("div",null,i)}const B=t(n,[["render",a]]);export{d as __pageData,B as default};
